400	\begin{lemma}[The Pauli question distribution is a typed CL distribution]\label{lem:pauli-question-typed-cl}
401		\lean{MIPStarRE.QPBT.pauliQuestionDistribution_eq_typedCL}
402		\uses{def:pauli-question-distribution, def:typed-cl-distributions, def:graph-distribution}
403		Fix an admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}) and let $L = \{L_t\}_{t \in \mathcal T^{\mathrm{pauli}}}$ be the family of Definition~\ref{def:pauli-question-distribution}. Then the question distribution of $\mathfrak{G}^{\mathrm{Pauli}}_{\mathsf{qldparams}}$ is the $(\mathcal T^{\mathrm{pauli}}, G^{\mathrm{pauli}})$-typed conditionally linear distribution $\mu^{G^{\mathrm{pauli}}}_{L,\,L}$ of Definition~\ref{def:typed-cl-distributions}.
404	\end{lemma}
405	\begin{proof}
406		\uses{def:typed-cl-distributions, def:graph-distribution, def:cl-dist}
407		The type pair is drawn from $\mu_{G^{\mathrm{pauli}}}$ by definition, and for each ordered type pair the content pair is the image of a single uniform $z \in V^{\mathrm{pauli}}$ under the corresponding pair of CL functions, that is, a sample from $\mu_{L_{t_{\mathrm A}},\, L_{t_{\mathrm B}}}$.
408	\end{proof}
